import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"配置详解","description":"","frontmatter":{},"headers":[],"relativePath":"modules/accessory/configuration.md","filePath":"modules/accessory/configuration.md","lastUpdated":0}`),a={name:`modules/accessory/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="配置详解" tabindex="-1">配置详解 <a class="header-anchor" href="#配置详解" aria-label="Permalink to “配置详解”">​</a></h1><p><code>plugins/EmakiAccessory/config.yml</code> 是主配置，<code>pages/*.yml</code> 定义饰品页。<code>version</code> 是配置结构标记，由项目资源同步流程维护，插件按它合并新增的默认键。</p><h2 id="顶层键" tabindex="-1">顶层键 <a class="header-anchor" href="#顶层键" aria-label="Permalink to “顶层键”">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td><code>&quot;1.0.3&quot;</code></td><td>配置结构版本，用于合并新增默认键。</td></tr><tr><td><code>language</code></td><td><code>&quot;zh_CN&quot;</code></td><td>语言文件名，对应 <code>lang/&lt;language&gt;.yml</code>。</td></tr><tr><td><code>release_default_data</code></td><td><code>true</code></td><td>是否在每次启动时释放插件内置的默认数据文件（<code>parts.yml</code>、<code>pages/</code>、<code>sets/</code> 下的示例文件）。为 true 时每次启动都会补齐缺失的默认示例，已存在的文件不会被覆盖；改为 false 后只保留已有数据，不再主动生成缺失示例。</td></tr><tr><td><code>drop_on_death</code></td><td><code>false</code></td><td>死亡时是否掉落饰品。</td></tr><tr><td><code>unique</code></td><td><code>true</code></td><td>是否禁止同时装备两件相同饰品。</td></tr><tr><td><code>slot_sources</code></td><td>见下文</td><td>追加的「可穿戴槽位」声明来源。</td></tr><tr><td><code>persistence</code></td><td>见下文</td><td>自动保存与关服落盘参数。</td></tr></tbody></table><h2 id="drop-on-death" tabindex="-1"><code>drop_on_death</code> <a class="header-anchor" href="#drop-on-death" aria-label="Permalink to “drop_on_death”">​</a></h2><p>为 <code>true</code> 时饰品会被<strong>追加到死亡掉落列表</strong>里，交给原版死亡流程处理，而不是塞回背包——后者会让同一件饰品同时存在于掉落物和背包中。</p><p>其他插件已经开启 <code>keepInventory</code> 时本项不生效，饰品一律保留。</p><h2 id="unique" tabindex="-1"><code>unique</code> <a class="header-anchor" href="#unique" aria-label="Permalink to “unique”">​</a></h2><p>优先按 <strong>EmakiItem 的物品定义 id</strong> 判定：同一个定义的两件饰品即使等级或词条不同也算重复。EmakiItem 不可用时回退为原版材质判定，因此同材质的两件饰品会被视为重复。</p><h2 id="slot-sources-穿戴槽位来源" tabindex="-1"><code>slot_sources</code> 穿戴槽位来源 <a class="header-anchor" href="#slot-sources-穿戴槽位来源" aria-label="Permalink to “slot_sources 穿戴槽位来源”">​</a></h2><p>一件饰品声明「能戴在哪些槽位」的额外读取来源。EmakiAttribute 的 <code>active_slot</code> 与 EmakiSkills 的技能载荷<strong>始终生效</strong>，下面两项是在此之上追加的来源；四个来源取并集，任一命中即允许穿戴。两项都关闭时行为与单一来源时一致。</p><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>slot_sources.pdc.enabled</code></td><td><code>false</code></td><td>是否从物品 PDC 读取槽位列表。</td></tr><tr><td><code>slot_sources.pdc.key</code></td><td><code>&quot;&quot;</code></td><td>NamespacedKey 全写，逐字使用填写值，不做大小写改写。优先按字符串列表读取，读不到时回退为单个字符串并按 <code>separator</code> 切分。</td></tr><tr><td><code>slot_sources.lore.enabled</code></td><td><code>false</code></td><td>是否从 Lore 用正则读取槽位列表。</td></tr><tr><td><code>slot_sources.lore.patterns</code></td><td>见默认资源</td><td>正则列表，每条的捕获组 1 是槽位列表文本。匹配前会去除 MiniMessage 标签并折叠空白，按纯文本书写。写错的正则只记录警告并跳过该条。</td></tr><tr><td><code>slot_sources.lore.separator</code></td><td><code>&quot;,&quot;</code></td><td>槽位列表分隔符，同时用于 <code>pdc</code> 的字符串回退分支。</td></tr><tr><td><code>slot_sources.lore.aliases</code></td><td>见默认资源</td><td>Lore 中文名到 <code>parts.yml</code> 部位 id 的映射。部位 id 只能是小写字母、数字和下划线，所以中文槽位名必须在这里转换；未列出的值按原样规范化后使用。</td></tr></tbody></table><h2 id="pages-yml-饰品页" tabindex="-1"><code>pages/*.yml</code> 饰品页 <a class="header-anchor" href="#pages-yml-饰品页" aria-label="Permalink to “pages/*.yml 饰品页”">​</a></h2><p>一个文件定义一页。页 id 取 <code>page_id</code>，与文件名无关。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">page_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">display_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;主饰品栏&lt;/gold&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">gui_template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;accessory_gui&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">parts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;necklace&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ring&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;belt&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;charm&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>page_id</code></td><td>页 id，也是数据文件里的存储分区键。</td></tr><tr><td><code>display_name</code></td><td>页显示名，支持 MiniMessage，用于切页格与 <code>/eacc pages</code>。</td></tr><tr><td><code>order</code></td><td>页排序，升序；<strong>最小者为默认启用页</strong>。</td></tr><tr><td><code>gui_template</code></td><td>该页使用的布局 id，允许多页共用一个布局。</td></tr><tr><td><code>permission</code></td><td>为空表示所有人可用；非空时逐字使用该权限串。</td></tr><tr><td><code>parts</code></td><td>本页启用的部位，取值必须是 <code>parts.yml</code> 里已定义的部位 id。</td></tr></tbody></table><p>三条页面规则：</p><ul><li><strong>存储隔离</strong>：同一个槽位实例 id 在不同页各存一件饰品，互不覆盖。</li><li><strong>只有启用页生效</strong>：其余页的饰品保留但不产生属性、技能与套装件数。</li><li><strong>失权不清数据</strong>：玩家失去启用页权限时数据不清除，也不自动换页；该页打不开、其饰品停止生效，玩家用 <code>/eacc retrieve &lt;页&gt;</code> 自行取回。</li></ul><p>部位在页里会按 <code>parts.yml</code> 的 <code>count</code> 展开成槽位实例，且必须在 <code>gui_template</code> 指向的布局里摆放，否则该槽位不可用并记录警告。</p><h2 id="persistence-持久化" tabindex="-1"><code>persistence</code> 持久化 <a class="header-anchor" href="#persistence-持久化" aria-label="Permalink to “persistence 持久化”">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>autosave_seconds</code></td><td><code>60</code></td><td>自动保存间隔（秒）。设为 0 或负数关闭定时保存。</td></tr><tr><td><code>drain_timeout_seconds</code></td><td><code>10</code></td><td>关服时等待未落盘写入完成的秒数。</td></tr></tbody></table><p>关闭定时保存后，仅在关闭窗口、玩家退出和服务器关服时落盘。</p><p><code>drain_timeout_seconds</code> 超时后会打印剩余脏数据条数并继续关服，不会无限等待卡住服务器关闭流程。</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};